import sys
sys.path.insert(0,'.')
from app.vcl import load_dfm, walk
F="/workspace/smarBankdelphi/Packages/Cards_New/cards_azericard/Unit18.dfm"
r=load_dfm(F)
objs=list(walk(r))
out=['"""Verbatim SQL of Packages/Cards_New/cards_azericard (Unit18.dfm TDataMod_CARDS, SQL.Strings line lists).',
'Each dataset is kept as its TStrings line list (LINES_<name>) because Delphi edits lines by index (Clients SQL[25]); text() joins',
'them with CRLF like TStrings.Text. Generated by tools/gen_cards_sql.py from the .dfm, do not hand-edit."""','',
'',
'def text(lines, **repl):','    """TStrings.Text after SQL[i] := value assignments (repl keys are i<index>)."""','    L = list(lines)',
'    for k, v in repl.items():','        L[int(k[1:])] = v','    return "\\r\\n".join(L) + "\\r\\n"','','']
src={}
for o in objs:
    if o.cls=='TDataSource': src[o.name]=o.props.get('DataSet')
for o in objs:
    if o.cls in('TOracleDataSet','TOracleQuery') and 'SQL.Strings' in o.props:
        out.append(f"# Unit18.dfm:{o.line} {o.name} ({o.cls})")
        out.append(f"LINES_{o.name.upper()} = {o.props['SQL.Strings']!r}")
out.append(f"SOURCES = {src!r}")
open('app/cards_sql.py','w').write('\n'.join(out)+'\n')
print(len([l for l in out if l.startswith('LINES_')]))
